<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/safety_vote_planning.php';

function svpl_gate():void {
    $tables=db_rows("SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('SafetyVote_AdminSavedViews','SafetyVote_CampaignTemplates')");
    if(count($tables)!==2)json_response(['success'=>false,'code'=>'SAFETY_VOTE_PLANNING_SETUP_REQUIRED','message'=>'Safety Vote planning migration is required.'],503);
    $setting=db_row("SELECT SettingValue FROM SafetyVote_Settings WHERE SettingKey='engagement_enabled'");
    if(($setting['SettingValue']??'0')!=='1')json_response(['success'=>false,'code'=>'SAFETY_VOTE_ENGAGEMENT_DISABLED','message'=>'Safety Vote engagement features are disabled.'],503);
}
function svpl_campaign_config(int$id):?array {
    $v=db_row("SELECT c.id campaignId,c.CampaignCode campaignCode,c.OwnerEmployeeID ownerEmployeeId,c.DiscoveryMode discoveryMode,c.CurrentVersionID currentVersionId,v.CampaignType campaignType,v.PrivacyMode privacyMode,v.TitleTh titleTh,v.TitleEn titleEn,v.Summary summary,v.Description description,v.RulesText rulesText,v.TimeZone timeZone,v.ResultVisibility resultVisibility,v.EditPolicy editPolicy,v.ScoringMethod scoringMethod,v.PrivacyThreshold privacyThreshold,v.AllowAbstain allowAbstain,v.RandomizeOptions randomizeOptions FROM SafetyVote_Campaigns c JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID WHERE c.id=? AND c.Status<>'Voided'",[$id]);
    if(!$v)return null;
    $questions=sv3_questions_db((int)$v['currentVersionId']);
    $rules=db_rows("SELECT RuleGroup ruleGroup,RuleOrder ruleOrder,Effect effect,AttributeKey attributeKey,Operator operator,ValuesJson valuesJson,Reason reason FROM SafetyVote_EligibilityRules WHERE CampaignVersionID=? AND IsActive=1 ORDER BY RuleGroup,RuleOrder,id",[$v['currentVersionId']]);
    foreach($rules as&$rule){$rule['values']=json_decode((string)$rule['valuesJson'],true)?:[];unset($rule['valuesJson']);}unset($rule);
    return['campaignId'=>(int)$v['campaignId'],'campaignCode'=>$v['campaignCode'],'version'=>$v,'questions'=>$questions,'rules'=>$rules];
}
function svpl_recipients(int$campaignId,string$audience):?array {
    $c=db_row("SELECT CurrentVersionID FROM SafetyVote_Campaigns WHERE id=? AND Status<>'Voided'",[$campaignId]);
    if(!$c||!in_array($audience,['eligible','nonparticipants'],true))return null;
    $sql="SELECT ev.EmployeeID,e.CompanyEmail FROM SafetyVote_EligibleVoters ev JOIN SafetyVote_EligibilitySnapshots es ON es.id=ev.SnapshotID LEFT JOIN Employees e ON BINARY e.EmployeeID=BINARY ev.EmployeeID WHERE es.CampaignVersionID=? AND es.Status='frozen'";
    if($audience==='nonparticipants')$sql.=" AND NOT EXISTS(SELECT 1 FROM SafetyVote_Participation p WHERE p.CampaignVersionID=es.CampaignVersionID AND p.EmployeeID=ev.EmployeeID AND p.State='submitted')";
    return db_rows($sql,[$c['CurrentVersionID']]);
}
function svpl_remove_file(?string$name):void {if(!$name)return;$file=sv_private_dir().DIRECTORY_SEPARATOR.basename($name);if(is_file($file))@unlink($file);}

