    $assets=route_params($path,'/safety-vote/admin/planning/campaigns/:id/assets');$attach=route_params($path,'/safety-vote/admin/planning/promotions/:promotionId/assets/:fileId');
    $notification=$path==='/safety-vote/admin/planning/notifications/preview';
    $reviewQueue=$path==='/safety-vote/admin/planning/review-queue';$governance=route_params($path,'/safety-vote/admin/planning/campaigns/:id/governance');$reviewNotes=route_params($path,'/safety-vote/admin/planning/campaigns/:id/review-notes');

