        foreach($campaigns as$row){$readiness=svpl_review_readiness($row);$assigned=[];foreach($roles as$roleRow)if((int)$roleRow['CampaignVersionID']===(int)$row['CurrentVersionID'])$assigned[]=['employeeId'=>$roleRow['EmployeeID'],'name'=>$roleRow['EmployeeName']?:null,'role'=>$roleRow['CampaignRole']];$state=$row['Status']==='Draft'?(count($readiness['blockers'])?'needs_attention':'ready_for_authoritative_check'):'monitoring';$rows[]=['id'=>(int)$row['id'],'campaignCode'=>$row['CampaignCode'],'title'=>$row['TitleTh'],'status'=>$row['Status'],'campaignType'=>$row['CampaignType'],'privacyMode'=>$row['PrivacyMode'],'updatedAt'=>$row['UpdatedAt'],'scheduledOpenAt'=>$row['ScheduledOpenAt'],'scheduledCloseAt'=>$row['ScheduledCloseAt'],'owner'=>['employeeId'=>$row['OwnerEmployeeID'],'name'=>$row['OwnerName']?:null],'assignees'=>$assigned,'readiness'=>$readiness,'scheduleConflictCount'=>(int)($conflicts[(int)$row['id']]??0),'derivedQueueState'=>$state];}return$rows;
    };
