    if($governance&&$method==='GET'){$id=svpl_int($governance['id']);$campaign=null;foreach($loadReviewRows()as$row)if($row['id']===$id){$campaign=$row;break;}if(!$campaign)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND'],404);$audit=db_rows('SELECT id,ActorEmployeeID,ActorRole,Action,TargetType,TargetID,BoundedDetail,OccurredAt FROM SafetyVote_AuditLogs WHERE CampaignID=? ORDER BY OccurredAt DESC,id DESC LIMIT 100',[$id]);$timeline=[];foreach($audit as$row){if(preg_match('/BALLOT|ANSWER|RESPONSE|VOTER|RECEIPT|JURY_SCORE|CANDIDATE/i',(string)$row['Action'].' '.(string)$row['TargetType']))continue;$timeline[]=['id'=>(int)$row['id'],'actorEmployeeId'=>$row['ActorEmployeeID'],'actorRole'=>$row['ActorRole'],'action'=>$row['Action'],'targetType'=>$row['TargetType'],'targetId'=>$row['TargetID'],'detail'=>$row['BoundedDetail'],'occurredAt'=>$row['OccurredAt']];}json_response(['success'=>true,'data'=>['campaign'=>$campaign,'timeline'=>$timeline,'reviewNotes'=>array_values(array_filter($timeline,fn($r)=>$r['action']==='SAFETY_VOTE_ADMIN_REVIEW_NOTE')),'classification'=>'restricted_governance','approvalState'=>false,'containsBallotData'=>false]]);}
    if($reviewNotes&&$method==='POST'){$id=svpl_int($reviewNotes['id']);$parsed=svpl_review_note(json_body());if(!$id||!$parsed['ok'])json_response(['success'=>false,'code'=>'VALIDATION_FAILED','details'=>$parsed['errors']],400);if(!db_row("SELECT id FROM SafetyVote_Campaigns WHERE id=? AND Status<>'Voided'",[$id]))json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND'],404);$x=$parsed['value'];sv_audit($u,'SAFETY_VOTE_ADMIN_REVIEW_NOTE','SafetyVote_Campaign',(string)$id,$x['note'],['category'=>$x['category'],'privacyClass'=>'governance_note_no_ballot_data'],$id);json_response(['success'=>true,'data'=>['campaignId'=>$id,'note'=>$x['note'],'category'=>$x['category'],'approvalState'=>false]],201);}

