    if($templateArchive&&$method==='POST'){$id=svpl_int($templateArchive['id']);$body=json_body();$version=svpl_int($body['rowVersion']??null);if(!$id||!$version)json_response(['success'=>false,'code'=>'VALIDATION_FAILED'],400);$updated=db_execute("UPDATE SafetyVote_CampaignTemplates SET Status='Archived',UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=? AND RowVersion=? AND Status='Active'",[sv_actor($u),$id,$version]);if(!$updated)json_response(['success'=>false,'code'=>'VERSION_CONFLICT'],409);sv_audit($u,'SAFETY_VOTE_TEMPLATE_ARCHIVE','SafetyVote_CampaignTemplate',(string)$id,'archived');json_response(['success'=>true,'data'=>['id'=>$id,'archived'=>true]]);}
