    if($assets&&$method==='GET'){$id=svpl_int($assets['id']);if(!$id)json_response(['success'=>false,'code'=>'VALIDATION_FAILED'],400);$rows=db_rows("SELECT f.id,f.FilePurpose,f.OriginalName,f.MimeType,f.FileSize,f.ContentSha256,f.UploadedAt FROM SafetyVote_Files f JOIN SafetyVote_Campaigns c ON c.id=f.CampaignID WHERE f.CampaignID=? AND f.CampaignVersionID=c.CurrentVersionID AND f.Status='Active' AND f.MimeType IN ('image/jpeg','image/png','image/webp') AND f.FilePurpose IN ('promotion_library','promotion_desktop','promotion_mobile') ORDER BY f.UploadedAt DESC,f.id DESC LIMIT 100",[$id]);foreach($rows as&$row)$row=['id'=>(int)$row['id'],'purpose'=>$row['FilePurpose'],'originalName'=>$row['OriginalName'],'mimeType'=>$row['MimeType'],'fileSize'=>(int)$row['FileSize'],'contentSha256'=>$row['ContentSha256'],'uploadedAt'=>$row['UploadedAt']];unset($row);json_response(['success'=>true,'data'=>['rows'=>$rows]]);}
    if($assets&&$method==='POST'){$id=svpl_int($assets['id']);$file=$_FILES['file']??null;if(!$id||!$file||(int)$file['error']!==UPLOAD_ERR_OK||(int)$file['size']>10*1024*1024)json_response(['success'=>false,'code'=>'FILE_UPLOAD_REJECTED'],400);$mime=sv_file_mime((string)$file['tmp_name']);if(!in_array($mime,['image/jpeg','image/png','image/webp'],true))json_response(['success'=>false,'code'=>'FILE_UPLOAD_REJECTED'],400);$campaign=db_row("SELECT id,CurrentVersionID FROM SafetyVote_Campaigns WHERE id=? AND Status<>'Voided'",[$id]);if(!$campaign)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND'],404);$ext=['image/jpeg'=>'.jpg','image/png'=>'.png','image/webp'=>'.webp'][$mime];$stored=time().'-'.bin2hex(random_bytes(18)).$ext;$target=sv_private_dir().DIRECTORY_SEPARATOR.$stored;if(!move_uploaded_file((string)$file['tmp_name'],$target))json_response(['success'=>false,'code'=>'FILE_UPLOAD_REJECTED'],500);try{db_execute("INSERT INTO SafetyVote_Files(CampaignID,CampaignVersionID,FilePurpose,StoredName,OriginalName,MimeType,FileSize,ContentSha256,UploadedBy) VALUES(?,?,'promotion_library',?,?,?,?,?,?)",[$id,$campaign['CurrentVersionID'],$stored,svpl_clean($file['name']??'',255),$mime,(int)$file['size'],hash_file('sha256',$target),sv_actor($u)]);$fileId=(int)db()->lastInsertId();sv_audit($u,'SAFETY_VOTE_ASSET_LIBRARY_UPLOAD','SafetyVote_File',(string)$fileId,'size='.(int)$file['size'].'; mime='.$mime,['sha256'=>hash_file('sha256',$target)],$id);json_response(['success'=>true,'data'=>['id'=>$fileId,'campaignId'=>$id,'originalName'=>svpl_clean($file['name']??'',255),'mimeType'=>$mime,'fileSize'=>(int)$file['size'],'contentSha256'=>hash_file('sha256',$target)]],201);}catch(Throwable$e){svpl_remove_file($stored);json_response(['success'=>false,'code'=>'ASSET_UPLOAD_FAILED'],500);}}
    if($attach&&$method==='POST'){$promotionId=svpl_int($attach['promotionId']);$fileId=svpl_int($attach['fileId']);$body=json_body();$slot=$body['slot']??'';$column=$slot==='mobile'?'MobileFileID':($slot==='desktop'?'DesktopFileID':null);if(!$promotionId||!$fileId||!$column)json_response(['success'=>false,'code'=>'VALIDATION_FAILED'],400);$owned=db_row("SELECT p.id,p.CampaignID,p.AltText FROM SafetyVote_Promotions p JOIN SafetyVote_Campaigns c ON c.id=p.CampaignID JOIN SafetyVote_Files f ON f.id=? AND f.CampaignID=p.CampaignID AND f.CampaignVersionID=c.CurrentVersionID AND f.Status='Active' AND f.MimeType IN ('image/jpeg','image/png','image/webp') WHERE p.id=?",[$fileId,$promotionId]);if(!$owned)json_response(['success'=>false,'code'=>'ASSET_OWNERSHIP_CONFLICT'],409);if(trim((string)($owned['AltText']??''))==='')json_response(['success'=>false,'code'=>'ASSET_ALT_TEXT_REQUIRED'],409);db_execute("UPDATE SafetyVote_Promotions SET $column=?,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?",[$fileId,sv_actor($u),$promotionId]);sv_audit($u,'SAFETY_VOTE_ASSET_LIBRARY_ATTACH','SafetyVote_Promotion',(string)$promotionId,'slot='.$column.'; file='.$fileId,[],$owned['CampaignID']);json_response(['success'=>true,'data'=>['promotionId'=>$promotionId,'fileId'=>$fileId,'slot'=>$slot]]);}
